package unverified;

import metadata.BehavioralDifference;
import metadata.DifferenceType;

import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static unverified.ClonePairGenericInvocationTestSupport.*;

@Tag("timeout")
class ClonePair9291DifferenceFindingTest {

    private final ClonePair9291 subject = new ClonePair9291();

    /**
     * Generated by Claude Code (Claude Fable 5.1).
     * Difference type: no_termination.
     * Difference manifestation: the methods differ in whether they terminate.
     */
    @Test
    @BehavioralDifference(DifferenceType.NO_TERMINATION)
    void methodsDisagreeOnEmptySourceAndEmptySearchString() {
        // With an empty search string method1 never advances past index 0 and loops forever,
        // whereas method2 detects that the match position equals the source length and returns.
        InvocationOutcome method1Outcome = captureWithTimeout(values -> subject.method1((String) values[0], (String) values[1], (String) values[2]), 1000L, "", "", "");
        InvocationOutcome method2Outcome = captureWithTimeout(values -> subject.method2((String) values[0], (String) values[1], (String) values[2]), 1000L, "", "", "");

        assertEquals("TIMEOUT", method1Outcome.status);
        assertEquals("OK", method2Outcome.status);
        assertEquals("String()", method2Outcome.valueSnapshot);
    }
}
